import io
import numpy as np
import pandas as pd
from scipy import stats

test_type = {{test_type}}
difference_method = {{difference_method}}
independence_method = {{independence_method}}
group_column = {{group_column}}
value_column = {{value_column}}
tail = {{tail}}
row_variable = {{row_variable}}
column_variable = {{column_variable}}
alpha = float({{alpha}})


def _to_frame(value):
    if isinstance(value, pd.DataFrame):
        return value.copy()
    if isinstance(value, bytes):
        for encoding in ('utf-8-sig', 'utf-8', 'gbk', 'gb18030'):
            try:
                return pd.read_csv(io.StringIO(value.decode(encoding)))
            except UnicodeDecodeError:
                continue
        raise RuntimeError('CSV 编码无法识别')
    if isinstance(value, str):
        return pd.read_csv(io.StringIO(value.lstrip('\ufeff')))
    raise RuntimeError('输入 data 必须是 CSV 文本或 DataFrame')


def _number(value, digits=6):
    try:
        value = float(value)
        return None if not np.isfinite(value) else round(value, digits)
    except (TypeError, ValueError):
        return value


def _p_text(value):
    return '< 0.000001' if value < 0.000001 else '= {:.6f}'.format(value)


def _p_display(value):
    # 论文报告不展示浮点下溢产生的 0.000e+00；极小值统一按规范写作 p < 0.001。
    return '< 0.001' if value < 0.001 else '{:.3f}'.format(value)


def _decision(value):
    return '拒绝 H0，支持 H1' if value < alpha else '不能拒绝 H0，现有证据不足以支持 H1'


def _tail_p(two_sided_p, statistic):
    if tail == '双尾':
        return two_sided_p
    if tail == '右尾':
        return two_sided_p / 2 if statistic > 0 else 1 - two_sided_p / 2
    if tail == '左尾':
        return two_sided_p / 2 if statistic < 0 else 1 - two_sided_p / 2
    raise RuntimeError('未知检验方向：' + str(tail))


if data is None:
    raise RuntimeError('请先连接并运行上游的数据导入插件')
if not 0 < alpha < 1:
    raise RuntimeError('显著性水平必须在 0 到 1 之间')
if test_type not in ('差异性检验', '独立性检验'):
    raise RuntimeError('请先选择检验类型')

df = _to_frame(data)
report = {'报告名称': '统计假设检验报告', '检验类型': test_type, '显著性水平 α': alpha}

if test_type == '差异性检验':
    method = difference_method
    if method not in ('独立样本 t 检验', '单因素方差分析（ANOVA）'):
        raise RuntimeError('请选择差异性检验的方法')
    if not group_column or not value_column:
        raise RuntimeError('请选择分组列和数值列')
    if group_column == value_column:
        raise RuntimeError('分组列和数值列不能是同一列')
    missing = [c for c in (group_column, value_column) if c not in df.columns]
    if missing:
        raise RuntimeError('数据中找不到列：' + '、'.join(map(str, missing)))
    clean = df[[group_column, value_column]].copy()
    clean[value_column] = pd.to_numeric(clean[value_column], errors='coerce')
    clean = clean.dropna()
    groups = [(str(label), values[value_column].to_numpy(dtype=float))
              for label, values in clean.groupby(group_column, sort=True)]
    groups = [(label, values) for label, values in groups if len(values) >= 2]

    if method == '独立样本 t 检验':
        if len(groups) != 2:
            raise RuntimeError('独立样本 t 检验要求恰好 2 组，且每组至少有 2 个有效数值；当前符合条件的分组数为 ' + str(len(groups)))
        (label1, sample1), (label2, sample2) = groups
        levene = stats.levene(sample1, sample2, center='median')
        equal_var = float(levene.pvalue) >= alpha
        result = stats.ttest_ind(sample1, sample2, equal_var=equal_var)
        statistic = float(result.statistic)
        p_value = float(_tail_p(float(result.pvalue), statistic))
        n1, n2 = len(sample1), len(sample2)
        mean1, mean2 = float(sample1.mean()), float(sample2.mean())
        sd1, sd2 = float(sample1.std(ddof=1)), float(sample2.std(ddof=1))
        pooled = np.sqrt(((n1 - 1) * sd1 ** 2 + (n2 - 1) * sd2 ** 2) / (n1 + n2 - 2))
        effect = (mean1 - mean2) / pooled if pooled > 0 else None
        significant = p_value < alpha
        relation = '存在显著差异' if significant else '未发现显著差异'
        test_name = 'Student 独立样本 t 检验' if equal_var else 'Welch 独立样本 t 检验'
        if tail == '双尾':
            h0 = 'μ({}) = μ({})：两组总体均值相等'.format(label1, label2)
            h1 = 'μ({}) ≠ μ({})：两组总体均值不相等'.format(label1, label2)
        elif tail == '右尾':
            h0 = 'μ({}) ≤ μ({})'.format(label1, label2)
            h1 = 'μ({}) > μ({})'.format(label1, label2)
        else:
            h0 = 'μ({}) ≥ μ({})'.format(label1, label2)
            h1 = 'μ({}) < μ({})'.format(label1, label2)
        report.update({
            '检验方法': test_name,
            '研究问题': '比较“{}”中 {} 与 {} 两组的“{}”总体均值'.format(group_column, label1, label2, value_column),
            '检验方向': tail,
            'H0（原假设）': h0,
            'H1（备择假设）': h1,
            '样本概况': '组 {}：n = {}，均值 = {}，标准差 = {}\n组 {}：n = {}，均值 = {}，标准差 = {}'.format(label1, n1, _number(mean1, 3), _number(sd1, 3), label2, n2, _number(mean2, 3), _number(sd2, 3)),
            '前提检验': 'Levene 检验：W = {}，p {}。{}'.format(_number(levene.statistic, 3), _p_display(float(levene.pvalue)), '方差齐，采用 Student t 检验。' if equal_var else '方差不齐，采用 Welch 校正。'),
            '核心检验结果': '{}：t({}) = {}，p {}'.format(test_name, _number(result.df, 3), _number(statistic, 3), _p_display(p_value)),
            '效应量与差值': '均值差（组 {} − 组 {}）= {}；Cohen d = {}'.format(label1, label2, _number(mean1 - mean2, 3), _number(effect, 3)),
            '统计决策': _decision(p_value),
            '统计结论': '在显著性水平 α={} 下，两组在“{}”上的均值{}。'.format(alpha, value_column, relation),
            '论文级分析': '采用{}比较“{}”不同组别的“{}”均值。结果显示，t({}) = {}，p {}。因此，在 α={} 的显著性水平下，{}，表明两组均值{}。'.format(test_name, group_column, value_column, _number(result.df, 3), _number(statistic, 3), _p_text(p_value), alpha, _decision(p_value), relation),
        })
    else:
        if len(groups) < 2:
            raise RuntimeError('单因素方差分析至少要求 2 组，且每组至少有 2 个有效数值')
        arrays = [values for _, values in groups]
        result = stats.f_oneway(*arrays)
        levene = stats.levene(*arrays, center='median')
        statistic, p_value = float(result.statistic), float(result.pvalue)
        combined = np.concatenate(arrays)
        grand_mean = float(combined.mean())
        ss_between = sum(len(values) * (float(values.mean()) - grand_mean) ** 2 for values in arrays)
        ss_total = float(((combined - grand_mean) ** 2).sum())
        eta_squared = ss_between / ss_total if ss_total > 0 else None
        relation = '至少有一组均值与其他组存在显著差异' if p_value < alpha else '未发现各组总体均值存在显著差异'
        group_summary = '；'.join('{}：n={}，均值={}，标准差={}'.format(label, len(values), _number(values.mean()), _number(values.std(ddof=1))) for label, values in groups)
        report.update({
            '检验方法': '单因素方差分析（ANOVA）',
            '研究问题': '检验“{}”各组在“{}”上的总体均值是否相同'.format(group_column, value_column),
            'H0（原假设）': 'μ1 = μ2 = … = μk：所有组的总体均值相等',
            'H1（备择假设）': '并非所有总体均值都相等：至少有一组均值不同',
            '样本概况': '总样本量 n = {}，共 {} 组\n{}'.format(len(combined), len(groups), group_summary.replace('；', '\n')),
            '前提检验': 'Levene 检验：W = {}，p {}。{}'.format(_number(levene.statistic, 3), _p_display(float(levene.pvalue)), '满足方差齐性要求。' if float(levene.pvalue) >= alpha else '方差齐性假设可能不满足，结果需谨慎解释。'),
            '核心检验结果': 'F({}, {}) = {}，p {}'.format(len(groups) - 1, len(combined) - len(groups), _number(statistic, 3), _p_display(p_value)),
            '效应量': 'η² = {}'.format(_number(eta_squared, 3)),
            '统计决策': _decision(p_value), '统计结论': '在显著性水平 α={} 下，{}。'.format(alpha, relation),
            '论文级分析': '以“{}”为分组因素、“{}”为因变量进行单因素方差分析。结果显示，F({}, {}) = {}，p {}，η² = {}。因此，在 α={} 的显著性水平下，{}，{}。'.format(group_column, value_column, len(groups) - 1, len(combined) - len(groups), _number(statistic, 3), _p_text(p_value), _number(eta_squared, 3), alpha, _decision(p_value), relation),
        })
else:
    method = independence_method
    if method not in ('自动选择', '卡方独立性检验', 'Fisher 精确检验'):
        raise RuntimeError('请选择独立性检验的方法')
    if not row_variable or not column_variable:
        raise RuntimeError('请选择行变量和列变量')
    if row_variable == column_variable:
        raise RuntimeError('行变量和列变量不能是同一列')
    missing = [c for c in (row_variable, column_variable) if c not in df.columns]
    if missing:
        raise RuntimeError('数据中找不到列：' + '、'.join(map(str, missing)))
    clean = df[[row_variable, column_variable]].dropna()
    if clean.empty:
        raise RuntimeError('行变量和列变量没有同时非缺失的有效记录')
    table = pd.crosstab(clean[row_variable], clean[column_variable])
    table = table.loc[table.sum(axis=1) > 0, table.sum(axis=0) > 0]
    if table.shape[0] < 2 or table.shape[1] < 2:
        raise RuntimeError('列联表至少需要 2 行和 2 列')
    chi = stats.chi2_contingency(table, correction=False)
    expected = np.asarray(chi.expected_freq, dtype=float)
    low_count = int((expected < 5).sum())
    low_ratio = float(low_count / expected.size)
    chi_valid = bool((expected >= 1).all() and low_ratio <= 0.20)
    is_2x2 = table.shape == (2, 2)
    chosen = method
    reason = ''
    if method == '自动选择':
        if chi_valid:
            chosen = '卡方独立性检验'
            reason = '列联表所有期望频数均不低于 1，且低于 5 的单元格占比不超过 20%，满足卡方近似条件，因此自动采用卡方独立性检验。'
        elif is_2x2:
            chosen = 'Fisher 精确检验'
            reason = '列联表不满足卡方近似条件，且为 2×2 表，因此自动采用 Fisher 精确检验。'
        else:
            raise RuntimeError('当前列联表不满足卡方检验条件，且不是 2×2 表，无法使用 Fisher 精确检验。请合并低频类别或增加样本量后重试')
    elif method == '卡方独立性检验':
        reason = '用户指定采用卡方独立性检验。' + ('列联表满足常用期望频数条件。' if chi_valid else '列联表不满足常用期望频数条件，卡方近似结果需谨慎解释。')
    else:
        if not is_2x2:
            raise RuntimeError('Fisher 精确检验在本插件 V1.0 中仅支持 2×2 列联表；当前列联表为 {}×{}'.format(*table.shape))
        reason = '用户指定采用 Fisher 精确检验。'

    if chosen == '卡方独立性检验':
        statistic, p_value, dof = float(chi.statistic), float(chi.pvalue), int(chi.dof)
        n = int(table.to_numpy().sum())
        phi2 = statistic / n
        cramers_v = np.sqrt(phi2 / max(1, min(table.shape[0] - 1, table.shape[1] - 1)))
        result_text = 'χ²({}) = {}，p {}'.format(dof, _number(statistic, 3), _p_text(p_value))
        statistic_fields = {'χ² 统计量': _number(statistic), '自由度 df': dof, 'p 值': _number(p_value), '效应量 Cramér V': _number(cramers_v)}
    else:
        odds_ratio, p_value = stats.fisher_exact(table.to_numpy(), alternative='two-sided')
        p_value, odds_ratio = float(p_value), float(odds_ratio)
        result_text = 'Fisher 精确检验 p {}，优势比 OR = {}'.format(_p_text(p_value), _number(odds_ratio, 3))
        statistic_fields = {'p 值': _number(p_value), '优势比 OR': _number(odds_ratio)}
    relation = '存在显著关联' if p_value < alpha else '未发现显著关联'
    report.update({
        '检验方法': chosen, '研究问题': '检验分类变量“{}”与“{}”是否相互独立'.format(row_variable, column_variable),
        'H0（原假设）': '“{}”与“{}”相互独立，不存在统计关联'.format(row_variable, column_variable),
        'H1（备择假设）': '“{}”与“{}”不独立，存在统计关联'.format(row_variable, column_variable),
        '方法选择说明': reason,
        '样本与列联表': '有效样本量 n={}；列联表维度 {}×{}；观测频数 {}'.format(int(table.to_numpy().sum()), *table.shape, table.to_numpy().tolist()),
        '卡方适用条件': '最小期望频数={}；低于 5 的单元格 {}/{}（{}）；{}'.format(_number(expected.min()), low_count, expected.size, '{:.1%}'.format(low_ratio), '满足' if chi_valid else '不满足'),
        **statistic_fields,
        '统计决策': _decision(p_value), '统计结论': '在显著性水平 α={} 下，变量“{}”与“{}”之间{}。'.format(alpha, row_variable, column_variable, relation),
        '论文级分析': '对分类变量“{}”与“{}”进行独立性检验。{}检验结果显示，{}。因此，在 α={} 的显著性水平下，{}，表明两变量之间{}。'.format(row_variable, column_variable, reason, result_text, alpha, _decision(p_value), relation),
    })

print('【统计假设检验报告】')
print('方法：' + str(report['检验方法']))
print('统计决策：' + str(report['统计决策']))
print('结论：' + str(report['统计结论']))
print('论文表述：' + str(report['论文级分析']))
return {'report': report}
